import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            x = int(next(iterator))
            y = int(next(iterator))
        except StopIteration:
            break

        if y < x:
            results.append("0 0")
        elif y % x != 0:
            results.append("0 0")
        else:
            b = y // x
            a = 1
            results.append(f"{a} {b}")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
